import {STAGES,apply,calculate,makeGoal,evaluation,tasks,current,dateAt,addDays,weekday,weekStart,planningDates} from './domain.mjs';
import {createBrowserApi,downloadBrowserExport} from './pages-backend.mjs';
const pagesApi=createBrowserApi();
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=d=>new Intl.DateTimeFormat('ru',{day:'numeric',month:'long'}).format(new Date(d+'T12:00Z'));
const num=n=>n==null?'—':new Intl.NumberFormat('ru',{maximumFractionDigits:1}).format(n);
let user=null,state=null,queue=[],config={},screen='today',saveStatus='saved',syncing=false,authEmail='',month=null,selectedDay=null,modalRestore=null;
const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('100-days-challenge-pages-cache-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('cache');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
function localGet(k){return new Promise((r,j)=>{const q=db.transaction('cache').objectStore('cache').get(k);q.onsuccess=()=>r(q.result);q.onerror=()=>j(q.error);});}
function localSet(k,v){return new Promise((r,j)=>{const t=db.transaction('cache','readwrite');t.objectStore('cache').put(v,k);t.oncomplete=r;t.onerror=()=>j(t.error);});}
async function clearLocal(){await new Promise((r,j)=>{const t=db.transaction('cache','readwrite');t.objectStore('cache').clear();t.oncomplete=r;t.onerror=()=>j(t.error);});}
async function persist(){if(user)await localSet('session',{user,state,queue,config});}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
async function api(path,options={}){return pagesApi(path,options);}

async function mutate(action){try{if(['onboard','restart'].includes(action.type))action.data.challengeId??=crypto.randomUUID();const next=structuredClone(state);apply(next,action);queue.push({id:crypto.randomUUID(),action});state=next;saveStatus='pending';await persist();render();await sync();}catch(e){toast(e.message);}}
async function sync(){if(syncing||!user||!queue.length)return;syncing=true;try{while(queue.length){const op=queue[0];const result=await api('/api/sync',{method:'POST',body:JSON.stringify({...op,baseRevision:state.revision})});queue.shift();state=result.state;for(const pending of queue){try{apply(state,pending.action);}catch{break;}}await persist();}saveStatus='saved';render();}catch(e){saveStatus=e.status?'error':'pending';if(e.status===409||(e.status===400&&e.message.includes('Подтвердите это ограничение')))await conflict();else if(e.status===401)toast('Войдите снова. Несинхронизированные записи остаются на устройстве.');else if(e.status){toast(e.message);openModal(`<h2>Изменение не сохранено</h2><p class="hint">${esc(e.message)}. Запись осталась в локальной очереди.</p><pre>${esc(JSON.stringify(queue[0]?.action,null,2))}</pre><button class="secondary" id="discard-op">Отменить эту запись и загрузить серверные данные</button>`);$('#discard-op').onclick=async()=>{queue.shift();const data=await api('/api/me');state=data.state;for(const op of queue)apply(state,op.action);await persist();closeModal();render();syncing=false;sync();};}await persist();renderStatus();}finally{syncing=false;}}
async function conflict(){const server=(await api('/api/me')).state;const op=queue[0];if(op.action.type==='day'){const day=server.days.find(x=>x.id===op.action.data.id);if(day?.closed&&!op.action.data.acknowledgeHistory){openModal(`<h2>День уже завершён</h2><p class="hint">Запись поступила после окончания дня. Можно сохранить её как исправление истории: процент обновится, ранее начисленный прогресс не изменится. Отметку тренировки задним числом сохранить нельзя.</p><button class="primary" id="late-edit">Сохранить показатели как исправление</button>`);$('#late-edit').onclick=async()=>{op.action.data.acknowledgeHistory=true;delete op.action.data.workoutResult;state=server;for(const x of queue)apply(state,x.action);await persist();closeModal();render();syncing=false;sync();};return;}}openModal(`<h2>Проверим изменения</h2><p class="hint">На другом устройстве уже появились новые данные. Ваш ввод сохранён в очереди. Выберите, как поступить с первой записью.</p><h3>Ваше изменение</h3><pre>${esc(JSON.stringify(op.action,null,2))}</pre><h3>Сейчас на сервере</h3><pre>${esc(JSON.stringify(op.action.type==='day'?server.days.find(x=>x.id===op.action.data.id)?.values:{revision:server.revision},null,2))}</pre><div class="actions"><button class="primary" id="keep-local">Применить мой ввод</button><button class="secondary" id="keep-server">Оставить серверный</button></div>`);$('#keep-local').onclick=async()=>{state=server;for(const x of queue)apply(state,x.action);await persist();closeModal();syncing=false;sync();};$('#keep-server').onclick=async()=>{queue.shift();state=server;for(const x of queue)apply(state,x.action);await persist();closeModal();render();syncing=false;sync();};}
function statusHTML(){return `<span class="status ${saveStatus==='pending'?'pending':saveStatus==='error'?'error':''}"><i class="dot"></i>${saveStatus==='pending'?'Сохраняем в браузере':saveStatus==='error'?'Не удалось сохранить':'Сохранено в браузере'}</span>`;}
function renderStatus(){const s=$('#save-status');if(s)s.innerHTML=statusHTML();}
const icons={today:'◷',calendar:'▦',stages:'◇',body:'↗',settings:'⚙',calories:'♨',protein:'◒',sugar:'◇',water:'♧',steps:'↟',workout:'✦',balance:'≋'};
const navs=[['today','Сегодня'],['calendar','Календарь'],['stages','Этапы'],['body','Прогресс тела'],['settings','Настройки']];
function render(){if(!user)return renderAuth();if(!state?.profile)return renderOnboarding();const c=current(state)??state.challenges.at(-1),today=dateAt(Date.now(),state.settings.timezone);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">✓</span><div><strong>100 дней</strong><small>ВАШ РИТМ ПЕРЕМЕН</small></div></div><nav class="nav">${navs.map(([id,name])=>`<button data-screen="${id}" class="${screen===id?'active':''}" aria-current="${screen===id?'page':'false'}"><span class="sym" aria-hidden="true">${icons[id]}</span>${name}</button>`).join('')}</nav><div class="sidebar-note"><span class="leaf">❧</span><p>Маленькие шаги.<br>Привычки надолго.</p></div></aside><main class="main"><header class="topbar"><span class="mobile-brand">✓ 100 дней</span><span class="top-label">ЛИЧНОЕ ПРОСТРАНСТВО · БЕЗ СПЕШКИ</span><span id="save-status">${statusHTML()}</span><span class="avatar" title="Личный дневник в этом браузере">${esc(user.email[0].toUpperCase())}</span></header>${config.trialReady?'<div class="banner">Версия GitHub Pages: данные сохраняются только в этом браузере. Входа по email и переноса между устройствами здесь нет. Для резервной копии скачивайте JSON.</div>':''}<div id="content"></div></main></div>`;document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>{screen=b.dataset.screen;selectedDay=null;render();window.scrollTo(0,0);});({today:renderToday,calendar:renderCalendar,stages:renderStages,body:renderBody,settings:renderSettings}[screen])();}
function heading(title,sub,tag=''){return `<div class="hello"><div><span class="eyebrow">100 дней · один шаг за другим</span><h1>${title}</h1><p class="subtitle">${sub}</p></div>${tag?`<span class="pill">${tag}</span>`:''}</div>`;}
function renderAuth(){if(config.trialReady){$('#app').innerHTML=`<div class="auth"><section class="auth-art"><div class="brand"><span class="brandmark">✓</span><strong>100 дней</strong></div><h1>Попробуем<br>в вашем темпе.</h1><p>Начните с первого запуска: заполните свои данные, посмотрите ориентиры и сохраните первый день.</p><div class="hundred" aria-hidden="true">100</div></section><section class="auth-form"><span class="eyebrow">Версия GitHub Pages</span><h2>Всё готово к проверке</h2><div class="banner">Версия GitHub Pages: данные сохраняются только в этом браузере. Входа по email и переноса между устройствами здесь нет. Для резервной копии скачивайте JSON.</div><p>Нажмите кнопку ниже. Затем приложение предложит заполнить возраст, рост, вес и дату начала. Фото и замеры можно добавить позже.</p><button class="primary" id="start-local-trial">Открыть дневник</button><p class="hint">Возвращайтесь по этой ссылке на том же устройстве и в том же браузере. Сохранённые данные останутся в этом браузере.</p></section></div>`;$('#start-local-trial').onclick=async()=>{try{await api('/api/trial',{method:'POST',body:'{}'});await load();}catch(e){toast(e.message);}};return;} $('#app').innerHTML=`<div class="auth"><section class="auth-art"><div class="brand"><span class="brandmark">✓</span><strong>100 дней</strong></div><h1>В своём темпе.<br>К новым привычкам.</h1><p>Питание, движение и немного заботы о себе — каждый день. Ваш прогресс остаётся с вами, даже после паузы.</p><div class="hundred" aria-hidden="true">100</div></section><section class="auth-form"><span class="eyebrow">Начнём с малого</span><h2>${authEmail?'Проверьте почту':'Ваш личный дневник'}</h2><p>${authEmail?`Введите код для ${esc(authEmail)}. Код из письма действует 10 минут.`:'Войдите по электронной почте. Без пароля, оплаты и рекламы.'}</p>${!config.authReady?'<div class="banner">Сервер запущен, но отправка кодов ещё не настроена. Владелец сервера должен задать почтовый API-ключ, адрес отправителя и AUTH_SECRET. Данные входа не имитируются.</div>':''}<form id="auth-form">${authEmail?'<label class="label">Код из письма<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label>':`<label class="label">Электронная почта<input type="email" name="email" autocomplete="email" placeholder="you@example.com" value="${esc(authEmail)}" required></label>`}<button class="primary" ${!config.authReady?'disabled':''}>${authEmail?'Войти':'Получить код'}</button></form>${authEmail?'<button class="ghost" id="other-email">Другой email / запросить новый код</button>':'<button class="ghost" id="have-code">У меня уже есть код</button>'}<p class="hint">Данные доступны только вашему аккаунту. Для личного устройства используется локальный кеш дневника; при выходе он удаляется.</p></section></div>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;try{if(authEmail){await api('/api/auth/verify',{method:'POST',body:JSON.stringify({email:authEmail,code:f.get('code')})});await load();}else{await api('/api/auth/request',{method:'POST',body:JSON.stringify({email:f.get('email')})});authEmail=f.get('email').trim().toLowerCase();renderAuth();}}catch(err){toast(err.message);}finally{b.disabled=false;}};if($('#have-code'))$('#have-code').onclick=()=>{const email=$('#auth-form input[name=email]');if(!email.reportValidity())return;authEmail=email.value.trim().toLowerCase();renderAuth();};if($('#other-email'))$('#other-email').onclick=()=>{authEmail='';renderAuth();};}
function input(name,label,type='number',value='',extra=''){return `<label class="label">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function profileFrom(f){return {age:+f.get('age'),sex:f.get('sex'),height:+f.get('height'),weight:+f.get('weight'),desiredWeight:+f.get('desiredWeight'),pal:+f.get('pal'),adult:f.get('adult')==='on',timezone:f.get('timezone'),pregnant:f.get('pregnant')==='on',breastfeeding:f.get('breastfeeding')==='on',individualDiet:f.get('individualDiet')==='on',trainingFrequency:+f.get('trainingFrequency'),initialComment:f.get('initialComment')??''};}

function fullDate(d){return new Intl.DateTimeFormat('ru',{day:'numeric',month:'long',year:'numeric'}).format(new Date(d+'T12:00Z'));}
function scenarioCards(calc,targetDate,selected='moderate'){
 const scenarios=calc.scenarios,preferred=scenarios[selected]?.allowed?selected:scenarios.moderate?.allowed?'moderate':scenarios.deadline?.allowed?'deadline':null;
 return '<div class="scenario-options">'+['deadline','moderate'].map(kind=>{const x=scenarios[kind],enabled=!!x?.allowed,title=kind==='deadline'?'К целевому весу к дате':'Умеренный вариант · ориентир 15%';
  return '<label class="scenario-card '+(enabled?'':'unavailable')+'"><span class="scenario-title"><input type="radio" name="scenario" value="'+kind+'" '+(preferred===kind?'checked ':'')+(enabled?'':'disabled')+'>'+title+'</span><strong class="scenario-calories">'+(x?.calories!=null?num(x.calories)+' <small>ккал/сутки</small>':'Недоступно')+'</strong><p class="hint">'+(x?.deficit!=null?'Дефицит: около '+num(x.deficit)+' ккал · '+num(x.percent)+'%':'')+'</p><p class="hint">'+(x?.predictedWeight!=null?'Модельный вес: около '+num(x.predictedWeight)+' кг к '+fullDate(targetDate)+' · '+scenarios.days+' дней.':'')+'</p>'+(!enabled?'<p class="scenario-warning">'+esc(x?.reason??calc.reasons.join(' '))+'</p>':'<span class="pill">Можно выбрать</span>')+'</label>';
 }).join('')+'</div><p class="hint">Оценочные сценарии при постоянной калорийности и прежней активности. «Умеренный» не означает универсально безопасный для каждого человека. Фактический вес может отличаться; статистический интервал не рассчитан.</p>';
}
function modelDetails(){return '<details class="hint"><summary>Как получены два значения</summary><p>Первый вариант подбирает постоянную калорийность к весу и сроку по динамической модели Hall/NIDDK. Второй использует дефицит 15% с ограничениями по нижней калорийности и максимальному дефициту. Модель учитывает изменение расхода, состава тела, гликогена и жидкости. Начальная жировая масса оценена по формуле Jackson, исходное питание принято равным поддержанию; доля углеводов 50%, натрий исходно 4000 мг с пропорциональным изменением — это расчётные допущения, не нормы питания. Тренировки дополнительно не прибавляются к расходу.</p><p>Проверена численная реализация по официальному коду NIDDK. Это не индивидуальная медицинская валидация или гарантия.</p></details>';}
function goalPlanningStart(c){const next=addDays(dateAt(Date.now(),state.settings.timezone),1);return c.start>next?c.start:next;}
function goalPanel(c,g){
 const start=goalPlanningStart(c),latest=state.body.filter(x=>x.weight!=null).sort((a,b)=>a.date.localeCompare(b.date)||a.created-b.created).at(-1),weight=latest?.weight??state.profile.weight;
 let target=state.profile.targetDate??g.targetDate??c.originalForecast.date;if(target<=start)target=addDays(start,100);
 const planning=planningDates(start,target),calc=calculate({...state.profile,weight,horizonDays:planning.days});
 return '<section class="card"><h2>Два варианта калорийности</h2><p class="hint">Поддержание: около <strong>'+num(calc.maintenance)+' ккал/сутки</strong>. Начало расчётного периода: '+fullDate(start)+'.</p><p class="hint">Принятая цель: '+(g.calories==null?'не назначена':num(g.calories)+' ккал')+' · действует с '+fullDate(g.effective)+'.</p><form id="goal-form"><div class="form-grid">'+input('desiredWeight','Желаемый вес, кг','number',state.profile.desiredWeight,'min="25" max="400" step="0.1" required')+input('targetDate','Дата достижения цели','date',target,'min="'+addDays(start,1)+'" max="'+addDays(start,730)+'" required')+'</div><div id="goal-comparison">'+scenarioCards(calc,target,g.scenario??'moderate')+'</div>'+modelDetails()+'<details><summary class="hint">Ручная корректировка калорийности</summary>'+input('calories','Своя цель, ккал · необязательно','number','','min="0" max="10000"')+'<p class="hint">Ручная цель проходит те же ограничения. При её вводе это отдельный сценарий; расчёт достижения желаемого веса к дате не применяется к этому числу.</p></details><button class="primary actions">Применить выбранный вариант</button></form><p class="hint">Применение требует вашего выбора. Новые нормы действуют со следующего дня; старые записи сохраняют свои цели.</p></section>';
}
function bindGoalPlanner(c){
 const form=$('#goal-form'),start=goalPlanningStart(c);let timer;
 const draw=()=>{try{const f=new FormData(form),planning=planningDates(start,f.get('targetDate')),latest=state.body.filter(x=>x.weight!=null).sort((a,b)=>a.date.localeCompare(b.date)||a.created-b.created).at(-1);const calc=calculate({...state.profile,weight:latest?.weight??state.profile.weight,desiredWeight:+f.get('desiredWeight'),horizonDays:planning.days});$('#goal-comparison').innerHTML=scenarioCards(calc,planning.targetDate,f.get('scenario')??'moderate');}catch(e){$('#goal-comparison').innerHTML='<p class="scenario-warning">'+esc(e.message)+'</p>';}};
 form.oninput=e=>{if(!['desiredWeight','targetDate'].includes(e.target.name))return;clearTimeout(timer);timer=setTimeout(draw,180);};
 form.onsubmit=e=>{e.preventDefault();clearTimeout(timer);const f=new FormData(form);if(!f.get('scenario')&&f.get('calories')==='')return toast('Нет доступного варианта: измените срок или целевой вес.');if(confirm('Применить выбранный вариант со следующего дня? Исторические нормы сохранятся.'))mutate({type:'goal',data:{desiredWeight:+f.get('desiredWeight'),targetDate:f.get('targetDate'),scenario:f.get('scenario')??'moderate',calories:f.get('calories')===''?undefined:+f.get('calories')}});};
}
function forecastPanel(c,g){const forecast=g.forecast;return '<section class="card"><h2>Расчётный сценарий</h2><p class="hint">'+(forecast?'При принятой калорийности '+num(g.calories)+' ккал модельный вес — около '+num(forecast.weight)+' кг к '+fullDate(g.targetDate??addDays(g.calculationStart??g.effective,forecast.days))+'.':'Для этой старой версии цели числовой сценарий ещё не сохранён. Выберите один из двух вариантов в настройках.')+'</p><p class="hint">Не гарантия результата. Два варианта и дата цели доступны в настройках.</p><p class="tiny">Исходные 100 календарных дней заканчиваются '+fullDate(c.originalForecast.date)+'. Паузы не продлевают срок. Обновление расчёта: '+esc(g.forecastUpdated??c.start)+'.</p><details class="hint"><summary>Первоначальный сценарий на 100 дней</summary><p>'+(c.originalForecast.scenarios?.moderate?'При исходном умеренном варианте: около '+num(c.originalForecast.scenarios.moderate.predictedWeight)+' кг к исходной дате.':'В версии, с которой начат этот челлендж, числовой прогноз не был сохранён.')+'</p></details></section>';}

function renderOnboarding(){const today=dateAt(Date.now(),Intl.DateTimeFormat().resolvedOptions().timeZone);$('#app').innerHTML=`<main class="onboarding"><div class="brand"><span class="brandmark">✓</span><strong>100 дней</strong></div>${config.trialReady?'<div class="banner">Версия GitHub Pages: данные сохраняются только в этом браузере. Входа по email и переноса между устройствами здесь нет. Для резервной копии скачивайте JSON.</div>':''}<span class="eyebrow">Ваше начало</span><h1>Знакомимся с вашим ритмом</h1><p class="subtitle">Немного исходных данных, чтобы подготовить дневник. Фото и замеры можно добавить позже.</p><form id="onboard"><section class="card"><h2>О вас</h2><div class="form-grid">${input('age','Возраст','number','','min="18" max="120" required')}<label class="label">Пол для расчётной формулы<select name="sex"><option value="female">Женская формула</option><option value="male">Мужская формула</option></select></label>${input('height','Рост, см','number','','min="100" max="250" step="0.1" required')}${input('weight','Текущий вес, кг','number','','min="25" max="400" step="0.1" required')}${input('desiredWeight','Желаемый вес, кг','number','','min="25" max="400" step="0.1" required')}${input('trainingFrequency','Тренировок в обычную неделю','number',0,'min="0" max="14" required')}</div><label class="label">Вся обычная активность, включая тренировки<select name="pal"><option value="1.4">Преимущественно сидячий режим · 1,4</option><option value="1.6">Лёгкая повседневная активность · 1,6</option><option value="1.8">Умеренная активность · 1,8</option><option value="2.2">Высокая активность · 2,2</option></select></label><p class="hint">Частота тренировок помогает выбрать общую активность. Отдельно калории тренировок не прибавляются.</p><label class="checkbox"><input name="adult" type="checkbox" required>Мне исполнилось 18 лет</label><label class="checkbox"><input name="pregnant" type="checkbox">Беременность</label><label class="checkbox"><input name="breastfeeding" type="checkbox">Грудное вскармливание</label><label class="checkbox"><input name="individualDiet" type="checkbox">Есть заболевание, лечение или другое состояние, требующее индивидуального питания, либо история расстройства пищевого поведения</label><p class="hint">Вне области автоматического расчёта доступен дневник без назначения дефицита. Это приложение не ставит диагнозы и не заменяет специалиста.</p></section><section class="card"><h2>Когда начинаем?</h2><div class="form-grid">${input('start','Дата начала','date',today,`min="${addDays(today,-365)}" max="${addDays(today,365)}" required`)}${input('targetDate','Дата достижения желаемого веса','date',addDays(today,100),`min="${addDays(today,1)}" max="${addDays(today,730)}" required`)}${input('timezone','Часовой пояс','text',Intl.DateTimeFormat().resolvedOptions().timeZone,'required')}</div><label class="label">Что хочется изменить? Необязательно<textarea name="initialComment" maxlength="2000" placeholder="Моя небольшая цель…"></textarea></label><p class="hint">В этой версии серверные уведомления недоступны. Вода и шаги на будущих этапах настраиваются на экране «Этапы».</p></section><button class="primary full" type="submit">Посмотреть расчёт</button><div id="calculation"></div></form></main>`;const form=$('#onboard'),targetField=form.elements.targetDate;let targetEdited=false;targetField.oninput=()=>{targetEdited=true;};form.elements.start.onchange=()=>{if(!targetEdited)targetField.value=addDays(form.elements.start.value,100);targetField.min=addDays(form.elements.start.value,1);targetField.max=addDays(form.elements.start.value,730);};form.oninput=e=>{if(e.target.name!=='scenario'&&$('#accept-start'))$('#calculation').innerHTML='';};form.onsubmit=e=>{e.preventDefault();try{const f=new FormData(form),p=profileFrom(f),planning=planningDates(f.get('start'),f.get('targetDate')),calc=calculate({...p,horizonDays:planning.days});$('#calculation').innerHTML='<div class="preview-output"><h2>Два варианта питания</h2><p>Поддержание: около <strong>'+num(calc.maintenance)+' ккал/сутки</strong>.</p><p class="hint">Период: '+fullDate(planning.start)+' — '+fullDate(planning.targetDate)+' · '+planning.days+' календарных дней.</p>'+scenarioCards(calc,planning.targetDate)+modelDetails()+'<button type="button" class="primary full" id="accept-start">'+(calc.eligible?'Принять выбранный вариант и начать':'Открыть дневник без дефицита')+'</button></div>';$('#accept-start').onclick=()=>{const choice=new FormData(form).get('scenario');if(calc.eligible&&!choice)return toast('Выберите допустимый вариант либо измените цель и срок.');mutate({type:'onboard',data:{profile:p,start:planning.start,targetDate:planning.targetDate,scenario:choice??'moderate'}});};$('#calculation').scrollIntoView({behavior:'smooth',block:'nearest'});}catch(err){toast(err.message);}};}

function ring(percent,done,total){return `<div class="ring"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="44"/><circle class="fg" cx="50" cy="50" r="44" stroke-dasharray="${276.46*percent/100} 276.46"/></svg><div>${percent}%<small>${done} ИЗ ${total} ЗАДАЧ</small></div></div>`;}
function taskHTML(t,d){const filled=t.value!==null,icon=icons[t.id]??'◇';let field=t.id==='workout'?`<select name="workoutResult" aria-label="Тренировка"><option value="">Не отмечено</option><option value="done" ${t.value==='done'?'selected':''}>Выполнено</option><option value="missed" ${t.value==='missed'?'selected':''}>Пропустить</option></select>`:t.id==='balance'?`<span class="tiny">${t.done?'В диапазонах':'Введите БЖУ ниже'}</span>`:`<input aria-label="${esc(t.title)}, ${t.unit}" type="number" inputmode="decimal" name="${t.id}" min="0" max="${t.id==='steps'?200000:50000}" step="${t.id==='steps'?'1':'0.1'}" value="${esc(t.value??'')}" placeholder="—">`;
  if(d.closed&&t.id==='workout')field=`<span class="tiny">${t.value==='done'?'Выполнено':'Пропущено'}</span>`;
  return `<div class="task" data-kind="${t.id}"><span class="task-icon" aria-hidden="true">${icon}</span><div><h3>${esc(t.title)}</h3><p>Цель: ${esc(t.target)} ${t.unit}</p>${filled?`<p>${t.done?'✓ Выполнено':'○ Ниже или вне цели'}</p>`:'<p>Пока нет данных</p>'}</div><div class="task-input">${field}<span class="check ${t.done?'':'empty'}" aria-label="${t.done?'Выполнено':'Не выполнено'}">${t.done?'✓':'·'}</span></div></div>`;}
function dayForm(d){const e=evaluation(d);return `<form id="day-form">${e.tasks.map(t=>taskHTML(t,d)).join('')}${d.diaryOnly?`<div class="banner">Режим дневника: автоматические нормы питания не назначены. Записи сохраняются, но не начисляют успешные дни программы.</div><div class="form-grid">${input('calories','Калории, ккал','number',d.values.calories??'','min="0" max="50000" step="0.1"')}${input('protein','Белок, г','number',d.values.protein??'','min="0" max="50000" step="0.1"')}</div>`:''}${d.stage>=8?`<div class="card"><h3>Дополняем БЖУ</h3><p class="hint">Белок берётся из задачи выше. Повторный ввод не нужен.</p><div class="form-grid">${input('fat','Жиры, г','number',d.values.fat??'','min="0" max="50000" step="0.1"')}${input('carbs','Углеводы, г','number',d.values.carbs??'','min="0" max="50000" step="0.1"')}</div></div>`:''}${d.stage>=3?'<details class="hint"><summary>Как считать продукты с добавленным сахаром?</summary>Введите общую калорийность всей порции — например, печенья, сладкого йогурта, конфет или напитка. Не только калории сахара. При цели 1800 ккал лимит — 360 ккал. Это правило челленджа, а не медицинская рекомендация. Введите 0, если таких продуктов не было; пустое поле означает отсутствие данных.</details>':''}<section class="card"><h3>Пара слов о дне <span class="tiny">· необязательно</span></h3><textarea class="note" name="note" maxlength="3000" placeholder="Что сегодня получилось?">${esc(d.note)}</textarea></section>${d.closed?'<div class="banner">Исправления обновят показатели и процент, но не изменят начисленный прогресс и уже начавшиеся этапы. Прошлые тренировки изменить нельзя.</div>':''}<div class="actions"><button class="primary" type="submit">${d.closed?'Сохранить исправления':'Сохранить день'}</button>${d.workout&&!d.closed&&d.workoutResult!=='done'?'<button class="ghost" type="button" id="move-workout">Перенести тренировку</button>':''}</div><p class="hint">${d.closed?'История правок сохраняется.':'Можно возвращаться к вводу до конца дня. Успешный день будет начислен после полуночи.'}</p><p class="hint">Записи сохраняются в этом браузере. Дни закрываются по часовому поясу при открытии или сохранении дневника; для копии истории используйте JSON-экспорт.</p></form>`;}
function bindDay(d){$('#day-form').onsubmit=async e=>{e.preventDefault();if(d.closed&&!confirm('Исправление не изменит ранее начисленный прогресс и этапы. Продолжить?'))return;const f=new FormData(e.target),values={};for(const k of ['calories','protein','sugar','water','steps','fat','carbs'])if(f.has(k))values[k]=f.get(k)===''?null:Number(f.get(k));const data={id:d.id,values,note:f.get('note'),acknowledgeHistory:d.closed};if(f.has('workoutResult')&&!d.closed)data.workoutResult=f.get('workoutResult')||null;await mutate({type:'day',data});};if($('#move-workout'))$('#move-workout').onclick=()=>{const c=state.challenges.find(x=>x.id===d.challengeId),available=[];for(let dt=addDays(d.date,1);weekStart(dt)===weekStart(d.date);dt=addDays(dt,1)){const schedule=c.scheduleVersions.filter(x=>x.effective<=dt).at(-1)?.days??state.settings.workoutDays;if(!schedule.includes(weekday(dt))&&!(c.moves??[]).some(x=>x.to===dt)&&!c.pauses.some(x=>dt>=x.from&&(!x.to||dt<x.to)))available.push(dt);}openModal(`<h2>Перенести тренировку</h2>${available.length?`<p class="hint">Исходный день станет днём отдыха. Перенос не означает выполнение.</p><form id="move-form"><label class="label">Новая дата<select name="date">${available.map(dt=>`<option value="${dt}">${pretty(dt)}</option>`).join('')}</select></label><button class="primary">Перенести</button></form>`:'<p>Доступных дат на этой неделе нет. Можно выполнить тренировку сегодня или пропустить её.</p>'}`);if($('#move-form'))$('#move-form').onsubmit=async e=>{e.preventDefault();const date=new FormData(e.target).get('date');closeModal();await mutate({type:'moveWorkout',data:{id:d.id,date}});};};}
function renderToday(){const c=current(state)??state.challenges.at(-1),today=dateAt(Date.now(),state.settings.timezone),d=state.days.find(x=>x.challengeId===c.id&&x.date===today),stage=c.stage,successIn=c.successes%10|| (c.status==='complete'?10:0),calDays=Math.max(0,Math.floor((Date.parse(today)-Date.parse(c.start))/86400000)+1);let body='';if(!d)body=`<div class="card empty-state">${c.status==='complete'?'Все 100 успешных дней пройдены. Ваши привычки остаются с вами!':`Начинаем ${pretty(c.start)}. Пока можно настроить будущие этапы.`}</div>`;else if(d.paused)body='<div class="card empty-state">Ⅱ Сейчас пауза. Это не пропуск.<br>Возобновить челлендж можно в настройках.</div>';else if([4,5,6,7,9].includes(d.stage)&&!c.stageSetups?.[d.stage])body=stageSetupHTML(d);else body=`${evaluation(d).success?'<div class="banner success">✓ Все задачи выполнены! Хорошая работа. День зачтётся после полуночи.</div>':''}<div class="section-head"><h2>Мой план на сегодня</h2><small>В вашем темпе</small></div>${dayForm(d)}`;const e=d?evaluation(d):{percent:0,done:0,total:0};$('#content').innerHTML=heading('Сегодня — ещё один шаг',`${pretty(today)} · ${new Intl.DateTimeFormat('ru',{weekday:'long',timeZone:state.settings.timezone}).format(new Date())}`,`✧ Этап ${stage} из 10`)+`<div class="grid"><div><section class="hero"><div class="hero-top"><div><span class="eyebrow">Ваш путь к привычкам</span><h2>${esc(STAGES[stage-1][0])}</h2><p>${successIn} из 10 успешных дней этапа</p></div>${ring(e.percent,e.done,e.total)}</div><div class="hero-bottom"><span>Выполнено ${c.successes} из 100 дней</span><div class="bar"><i>${'&nbsp;'.repeat(Math.ceil(c.successes/2))}</i></div><span>${calDays} календ. дн.</span></div></section>${body}</div><aside><section class="card quote"><div class="quote-icon">“</div><p>${['Не обязательно идеально. Достаточно продолжать.','У каждого маленького шага есть значение.','Вы выбираете свой темп. Прогресс остаётся с вами.'][new Date().getDate()%3]}</p><small>НАПОМИНАНИЕ НА СЕГОДНЯ</small></section><section class="card next"><span class="eyebrow">${stage<10?'Следующий этап':'Финиш — это начало'}</span><div class="next-icon">${stage<10?'✧':'❧'}</div><h3>${esc(STAGES[Math.min(stage,9)][0])}</h3><p>${esc(STAGES[Math.min(stage,9)][1])}</p><div class="bar"><i>${'&nbsp;'.repeat(successIn*3)}</i></div><span class="tiny">${stage<10?`Ещё ${10-successIn} успешных дней · без гарантированной даты`:'Сохраните личный режим в заметке дня'}</span></section><p class="hint">Пропуски не обнуляют путь. Частично заполненный день тоже сохраняется.</p></aside></div>`;if($('#stage-setup'))bindStageSetup(d);else if(d&&!d.paused)bindDay(d);}
function stageSetupHTML(d){
 const field=d.stage===6?'<div class="week-picker">'+['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map((x,i)=>'<label>'+x+'<input type="checkbox" name="day" value="'+i+'" '+(state.settings.workoutDays.includes(i)?'checked':'')+'></label>').join('')+'</div>':input(d.stage===4?'water':'steps',d.stage===4?'Чистая вода, мл':'Шаги в день','number',d.stage===4?d.water:d.steps,'min="0" max="'+(d.stage===4?'10000':'100000')+'" required');
 return '<section class="card"><span class="eyebrow">Новый этап · '+d.stage+' из 10</span><h2>'+esc(STAGES[d.stage-1][0])+'</h2><p class="hint">'+esc(STAGES[d.stage-1][2])+' Подтвердите удобную цель перед первым вводом. Требования прошлых этапов сохраняются.</p><form id="stage-setup">'+field+'<button class="primary actions">Принять настройки этапа</button></form></section>';
}
function bindStageSetup(d){$('#stage-setup').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);mutate({type:'stageSetup',data:d.stage===6?{workoutDays:f.getAll('day').map(Number)}:{[d.stage===4?'water':'steps']:+f.get(d.stage===4?'water':'steps')}});};}
function renderCalendar(){const c=current(state)??state.challenges.at(-1),today=dateAt(Date.now(),state.settings.timezone);month??=today.slice(0,7);const first=month+'-01',last=addDays(addMonths(first,1),-1),days=state.days.filter(x=>x.challengeId===c.id),cells=[];for(let i=0;i<weekday(first);i++)cells.push('<span></span>');for(let dt=first;dt<=last;dt=addDays(dt,1)){const d=days.find(x=>x.date===dt),e=d?evaluation(d):null;const kind=d?.paused?'paused':d?.closed?(e.success?'good':e.done?'partial':'missed'):dt>today||dt<c.start?'future':'';const label=d?.paused?'Ⅱ Пауза':d?.closed?`${e.success?'✓':e.done?'◐':'○'} ${e.percent}%`:dt===today?'◷ Сегодня':'·';cells.push(`<button class="calendar-day ${kind} ${dt===today?'today':''}" data-date="${dt}" aria-label="${pretty(dt)} ${label}"><b>${+dt.slice(-2)}</b><small>${label}</small></button>`);}$('#content').innerHTML=heading('Каждый день — часть пути','Успешные дни не обязаны идти подряд.')+`<div class="card"><div class="calendar-head"><button class="secondary" id="prev-month" aria-label="Предыдущий месяц">‹</button><h2>${new Intl.DateTimeFormat('ru',{month:'long',year:'numeric'}).format(new Date(first+'T12:00Z'))}</h2><button class="secondary" id="next-month" aria-label="Следующий месяц">›</button></div><div class="calendar-grid">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map(x=>`<span class="weekday">${x}</span>`).join('')}${cells.join('')}</div><div class="legend"><span>✓ Успешный</span><span>◐ Частичный</span><span>○ Пропуск</span><span>Ⅱ Пауза</span><span>· Будущий</span></div><p class="hint">Будущие этапы откроются по мере успешных дней. Даты не гарантированы. После исправления истории процент может отличаться от ранее начисленного прогресса.</p></div><div id="calendar-detail"></div>`;$('#prev-month').onclick=()=>{month=addMonths(first,-1).slice(0,7);renderCalendar();};$('#next-month').onclick=()=>{month=addMonths(first,1).slice(0,7);renderCalendar();};document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{const d=days.find(x=>x.date===b.dataset.date);if(!d)return toast('На эту дату ещё нет записи');if(d.paused)return toast('День паузы — без задач и пропуска');if(!d.closed&&[4,5,6,7,9].includes(d.stage)&&!c.stageSetups?.[d.stage]){screen='today';render();return;}selectedDay=d.id;$('#calendar-detail').innerHTML=`<div class="section-head"><h2>${pretty(d.date)} · ${evaluation(d).percent}%</h2><small>${d.credited?'✓ Ранее зачтён':d.closed?'Не зачтён':'День открыт'}</small></div>${dayForm(d)}<details class="hint"><summary>История правок (${state.audit.filter(x=>x.dayId===d.id).length})</summary>${state.audit.filter(x=>x.dayId===d.id).map(a=>`<p>${new Date(a.at).toLocaleString('ru')}<br>${esc(JSON.stringify(a.before.values))} → ${esc(JSON.stringify(a.after.values))}</p>`).join('')}</details>`;bindDay(d);$('#calendar-detail').scrollIntoView({behavior:'smooth'});});}
function addMonths(d,n){const dt=new Date(d+'T12:00Z');dt.setUTCMonth(dt.getUTCMonth()+n);return dt.toISOString().slice(0,10);}
function renderStages(){const c=current(state)??state.challenges.at(-1);$('#content').innerHTML=heading('Привычки, которые остаются','10 этапов. На каждом — 10 успешных дней.',`${c.successes} / 100`)+STAGES.map(([name,desc,hint],i)=>{const n=i+1,done=state.awards.some(a=>a.challengeId===c.id&&a.stage===n);return `<section class="card ${n===c.stage?'stage-current':''}"><div class="stage-row ${n>c.stage?'locked':''}"><span class="stage-number">${done?'✓':String(n).padStart(2,'0')}</span><div><h3>${esc(name)}</h3><p>${esc(desc)}</p></div><span class="pill">${done?'✧ Награда':n===c.stage?'Сейчас':`${i*10+1}–${n*10}`}</span></div><p class="hint">${esc(hint)}</p>${[4,5,7,9].includes(n)?`<form data-stage="${n}" class="actions"><label class="label">${n===4?'Вода, мл':'Шаги'}<input name="target" type="number" min="0" max="${n===4?10000:100000}" value="${n===4?state.settings.stageWater[n]??1500:state.settings.stageSteps[n]??(n===5?6000:n===7?8000:10000)}" required></label><button class="secondary">Настроить цель</button></form><p class="tiny">До открытия этапа можно выбрать удобную цель. После открытия изменение применяется к следующим дням; история сохраняет прежнюю норму.</p>`:''}</section>`;}).join('')+'<p class="hint">Привычки накапливаются. Повышение шагов заменяет предыдущую цель. Последний этап не добавляет обязательную задачу.</p>';document.querySelectorAll('[data-stage]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const stage=+f.dataset.stage,target=+new FormData(f).get('target');mutate({type:'settings',data:{stage,[stage===4?'water':'steps']:target}});});}
function chart(entries,key,label){const data=entries.map(x=>({date:x.date,v:key==='weight'?x.weight:x.measurements[key]})).filter(x=>x.v!=null).sort((a,b)=>a.date.localeCompare(b.date));if(!data.length)return '<p class="empty-state">Пока нет измерений</p>';let min=Math.min(...data.map(x=>x.v)),max=Math.max(...data.map(x=>x.v));if(max===min){min-=1;max+=1;}const firstTime=Date.parse(data[0].date),timeSpan=Date.parse(data.at(-1).date)-firstTime;const xs=data.map((x,i)=>[50+(timeSpan?(Date.parse(x.date)-firstTime)/timeSpan:.5)*480,150-(x.v-min)/(max-min)*110]);return `<svg class="chart" viewBox="0 0 580 200" role="img" aria-label="${label}. ${esc(data.map(x=>x.date+': '+x.v).join('; '))}"><line x1="50" y1="40" x2="530" y2="40"/><line x1="50" y1="95" x2="530" y2="95"/><line x1="50" y1="150" x2="530" y2="150"/><text x="8" y="44">${num(max)}</text><text x="8" y="154">${num(min)}</text><polyline points="${xs.map(p=>p.join(',')).join(' ')}"/>${xs.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="3.5"/>`).join('')}<text x="50" y="185">${pretty(data[0].date)}</text><text x="440" y="185">${pretty(data.at(-1).date)}</text></svg>`;}
function renderBody(){const entries=state.body.filter(x=>x.weight!=null).sort((a,b)=>a.date.localeCompare(b.date)||a.created-b.created),initial=entries[0]?.weight,latest=entries.at(-1)?.weight,c=current(state)??state.challenges.at(-1),goal=state.goals.filter(x=>x.challengeId===c.id).at(-1),recalc=latest!=null&&goal?.weight-latest>=5;const measurements={waist:'Талия',hips:'Бёдра',chest:'Грудь',abdomen:'Живот',leg:'Нога'};$('#content').innerHTML=heading('Меняется тело. Растут привычки.','Только ваши фактические изменения. Фото и замеры необязательны.')+`${recalc?'<div class="banner">Вес снизился на 5 кг или больше от последнего принятого расчёта. Можно пересчитать ориентиры в настройках. Изменения применятся только после вашего согласия.</div>':''}<div class="stat-grid"><div class="stat"><small>Исходный вес</small><strong>${num(initial)} кг</strong></div><div class="stat"><small>Текущий вес</small><strong>${num(latest)} кг</strong></div><div class="stat"><small>Изменение</small><strong>${latest==null?'—':num(latest-initial)} кг</strong></div></div><section class="card"><div class="section-head"><h2>Вес</h2><button class="secondary" id="add-body">+ Записать</button></div>${chart(state.body,'weight','Вес, кг')}<p class="hint">Вес может колебаться. Каждая запись — просто наблюдение.</p></section><section class="card"><h2>Замеры</h2><label class="label">Показатель<select id="measurement">${Object.entries(measurements).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><div id="measurement-chart">${chart(state.body,'waist','Талия, см')}</div><div id="measurement-delta"></div></section><section class="card"><div class="section-head"><h2>Фотографии прогресса</h2><button class="secondary" id="add-photo">+ Фото</button></div><p class="hint">Можно добавить на старте и после 25, 50, 75 и 100 успешных дней. Сейчас: ${c.successes}. Выберите две фотографии для сравнения.</p><div class="form-grid">${[0,1].map((n)=>`<label class="label">Фото ${n+1}<select class="photo-select" data-slot="${n}"><option value="">Не выбрано</option>${state.photos.map((p,i)=>`<option value="${p.id}" ${(n===0&&i===0)||(n===1&&i===state.photos.length-1)?'selected':''}>${pretty(p.date)}</option>`).join('')}</select></label>`).join('')}</div><div class="photo-grid" id="photos"></div></section>${forecastPanel(c,goal)}<section class="card"><h2>История веса</h2>${entries.slice().reverse().map(x=>`<div class="history-item"><span>${pretty(x.date)}</span><strong>${num(x.weight)} кг</strong></div>`).join('')}</section>`;$('#add-body').onclick=bodyModal;$('#measurement').onchange=e=>{const k=e.target.value;$('#measurement-chart').innerHTML=chart(state.body,k,measurements[k]+', см');const vals=state.body.filter(x=>x.measurements[k]!=null).sort((a,b)=>a.date.localeCompare(b.date));$('#measurement-delta').textContent=vals.length?`Исходно: ${num(vals[0].measurements[k])} см · Сейчас: ${num(vals.at(-1).measurements[k])} см · Изменение: ${num(vals.at(-1).measurements[k]-vals[0].measurements[k])} см`:'';};$('#measurement').dispatchEvent(new Event('change'));function photos(){const ids=[...document.querySelectorAll('.photo-select')].map(x=>x.value);$('#photos').innerHTML=ids.map(id=>{const p=state.photos.find(x=>x.id===id);return p?`<figure><img src="${esc(p.dataURL??'')}" alt="Фото прогресса ${pretty(p.date)}"><figcaption>${pretty(p.date)}</figcaption></figure>`:'';}).join('');}document.querySelectorAll('.photo-select').forEach(s=>s.onchange=photos);photos();$('#add-photo').onclick=photoModal;}
function bodyModal(){const today=dateAt(Date.now(),state.settings.timezone);openModal(`<h2>Записать наблюдение</h2><form id="body-form">${input('date','Дата','date',today,`max="${today}" required`)}${input('weight','Вес, кг · необязательно','number','','min="25" max="400" step="0.1"')}<div class="form-grid">${Object.entries({waist:'Талия',hips:'Бёдра',chest:'Грудь',abdomen:'Живот',leg:'Нога'}).map(([k,v])=>input(k,v+', см','number','','min="1" max="400" step="0.1"')).join('')}</div><p class="measure-guide">Измеряйте в одинаковое время, не затягивая ленту, на спокойном выдохе. Талия — между нижним ребром и верхом тазовой кости; бёдра — по наиболее выступающим точкам; грудь — горизонтально по наиболее выступающей части; живот — на уровне пупка; нога — на одной выбранной высоте бедра и с одной стороны.</p><button class="primary full">Сохранить</button></form>`);$('#body-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),measurements={};for(const k of ['waist','hips','chest','abdomen','leg'])if(f.get(k)!=='')measurements[k]=+f.get(k);if(f.get('weight')===''&&!Object.keys(measurements).length)return toast('Введите хотя бы одно наблюдение');closeModal();await mutate({type:'body',data:{date:f.get('date'),weight:f.get('weight')===''?null:+f.get('weight'),measurements}});if(f.get('weight')!=='')toast('Наблюдение сохранено. Спасибо, что нашли время для себя.');};}
function photoModal(){if(queue.length)return toast('Сначала синхронизируйте дневник');openModal(`<h2>Фото прогресса</h2><form id="photo-form">${input('date','Дата','date',dateAt(Date.now(),state.settings.timezone),'required')}<label class="label">JPEG, PNG или WebP · до 5 МБ<input name="file" type="file" accept="image/jpeg,image/png,image/webp" required></label><p class="hint">Фото сохраняется в этом браузере. Для резервной копии используйте экспорт.</p><button class="primary">Загрузить</button></form>`);$('#photo-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),file=f.get('file');if(file.size>5e6)return toast('Выберите фото до 5 МБ');const button=e.target.querySelector('button');button.disabled=true;try{const base64=await new Promise((r,j)=>{const reader=new FileReader();reader.onload=()=>r(reader.result.split(',')[1]);reader.onerror=j;reader.readAsDataURL(file);});const result=await api('/api/photos',{method:'POST',body:JSON.stringify({date:f.get('date'),mime:file.type,base64})});state=result.state;await persist();closeModal();render();toast('Фото сохранено');}catch(err){toast(err.message);}finally{button.disabled=false;}};}
function renderSettings(){const c=current(state)??state.challenges.at(-1),today=dateAt(Date.now(),state.settings.timezone),g=state.goals.filter(x=>x.challengeId===c.id).at(-1),paused=c.pauses.some(x=>!x.to);$('#content').innerHTML=heading('Ваши правила и ваш ритм','Настройки помогают подстроить челлендж под жизнь.')+`<div class="grid"><div>${goalPanel(c,g)}<section class="card"><h2>Тренировки</h2><p class="hint">Три дня в неделю, начиная с этапа 6. Изменение расписания — с будущего понедельника. На первой неделе прошлые дни не добавляются.</p><form id="schedule-form"><div class="week-picker">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map((x,i)=>`<label>${x}<input type="checkbox" name="day" value="${i}" ${state.settings.workoutDays.includes(i)?'checked':''}></label>`).join('')}</div><button class="secondary actions">Сохранить расписание</button></form></section><section class="card"><h2>Напоминания</h2><p class="hint">Утром — план дня. Вечером — только если остались пустые поля. Заполненное значение ниже цели не вызывает напоминание. На паузе уведомления отключены. Доставка зависит от разрешений, сети и Android.</p>${!config.pushReady?'<div class="banner">В версии GitHub Pages серверные push недоступны. План дня доступен в приложении.</div>':''}<form id="reminder-form"><div class="form-grid">${input('morning','Утренний план','time',state.settings.morning,'required')}${input('evening','Вечернее напоминание','time',state.settings.evening,'required')}</div><label class="checkbox"><input type="checkbox" name="morningEnabled" ${state.settings.morningEnabled?'checked':''}>Отправлять утренний план</label><label class="checkbox"><input type="checkbox" name="eveningEnabled" ${state.settings.eveningEnabled?'checked':''}>Напоминать вечером</label><button class="secondary">Сохранить время</button></form><button class="ghost" id="enable-push">Разрешить уведомления на устройстве</button></section><section class="card"><h2>Часовой пояс</h2><form id="zone-form">${input('timezone','Название IANA','text',state.settings.timezone,'required')}<p class="hint">Существующие дни сохраняют исходный часовой пояс и момент закрытия. Смена зоны не создаёт второй экземпляр дня с той же датой.</p><button class="secondary">Сохранить</button></form></section></div><aside><section class="card"><h2>Челлендж</h2>${c.start>today?`<form id="start-form">${input('date','Новая дата старта','date',c.start,`min="${today}" required`)}<button class="secondary">Изменить старт</button></form>`:''}<p class="hint">Пауза и возобновление действуют со следующего дня. Исходный прогноз не продлевается.</p><button class="secondary full" id="pause">${paused?'Продолжить со следующего дня':'Поставить на паузу'}</button><button class="ghost" id="restart">Завершить и начать новый</button></section><section class="card"><h2>Интеграции</h2><div class="history-item"><span>FatSecret</span><span>Не подключён</span></div><div class="history-item"><span>HONOR Здоровье</span><span>Не подключён</span></div><p class="hint">Доступ к личным данным этих сервисов ещё не подтверждён. Все показатели вводятся вручную. Автоматического импорта нет.</p></section><section class="card"><h2>Ваши данные</h2><p class="hint">Личный дневник в этом браузере</p><div class="actions"><a class="secondary" href="#export-csv" data-pages-export="csv">CSV</a><a class="secondary" href="#export-json" data-pages-export="json">JSON</a><a class="secondary" href="#export-photos" data-pages-export="photos">Фото · TAR</a></div><p class="hint">Экспорт содержит записи из этого браузера. Скачивайте JSON, чтобы иметь отдельную копию истории.</p><button class="ghost" id="retry-sync">Повторить синхронизацию (${queue.length})</button><button class="ghost" id="logout">Закрыть дневник</button><button class="secondary danger full" id="delete-account">Удалить данные из браузера</button><p class="hint">Серверных копий в этой версии нет. Очистка данных браузера или удаление данных приложения может удалить историю.</p></section><section class="card"><h2>Архив и награды</h2>${state.challenges.filter(x=>x.status!=='active').map(x=>`<div class="history-item"><span>${x.start}<br>${x.successes} успешных дней</span><button class="ghost archive" data-id="${x.id}">Открыть</button></div>`).join('')||'<p class="hint">Здесь появятся завершённые челленджи.</p>'}<p class="hint">Получено наград: ${state.awards.length}. Награды сохраняются после нового старта.</p></section><button class="secondary full" id="install-app">Установить на телефон</button></aside></div>`;
  bindGoalPlanner(c);
  $('#schedule-form').onsubmit=e=>{e.preventDefault();mutate({type:'settings',data:{workoutDays:new FormData(e.target).getAll('day').map(Number)}});};
  $('#reminder-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);mutate({type:'settings',data:{morning:f.get('morning'),evening:f.get('evening'),morningEnabled:f.has('morningEnabled'),eveningEnabled:f.has('eveningEnabled')}});};
  $('#zone-form').onsubmit=e=>{e.preventDefault();mutate({type:'settings',data:{timezone:new FormData(e.target).get('timezone')}});};
  if($('#start-form'))$('#start-form').onsubmit=e=>{e.preventDefault();mutate({type:'startDate',data:{date:new FormData(e.target).get('date')}});};
  $('#pause').onclick=()=>mutate({type:'pause',data:{resume:paused}});$('#restart').onclick=()=>{if(confirm('Завершить текущий челлендж? Он останется в архиве. Новый начнётся завтра.'))mutate({type:'restart',data:{confirm:true}});};
  $('#retry-sync').onclick=()=>sync();$('#logout').onclick=async()=>{if(queue.length&&!confirm('Есть несинхронизированные записи. При выходе локальная очередь будет удалена. Всё равно выйти?'))return;try{await api('/api/logout',{method:'POST',body:'{}'});await clearLocal();user=null;state=null;queue=[];authEmail='';render();}catch(e){toast('Для полного выхода подключитесь к интернету.');}};
  $('#delete-account').onclick=()=>{openModal(`<h2>Удалить данные из браузера?</h2><p class="hint">Дневник, фото и история будут удалены из этого браузера. Отменить это действие нельзя. Сначала можно скачать JSON-копию.</p><form id="delete-form">${input('email','Введите слово УДАЛИТЬ для подтверждения','text','','required')}<button class="primary danger">Удалить все данные</button></form>`);$('#delete-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/account',{method:'DELETE',body:JSON.stringify({confirm:new FormData(e.target).get('email')})});await clearLocal();closeModal();user=null;state=null;queue=[];render();toast('Данные удалены');}catch(err){toast(err.message);}};};
  $('#enable-push').onclick=enablePush;$('#install-app').onclick=async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else toast('Откройте меню браузера → «Установить приложение» или «На главный экран». Нужен HTTPS.');};
  document.querySelectorAll('.archive').forEach(b=>b.onclick=()=>{const days=state.days.filter(x=>x.challengeId===b.dataset.id);openModal(`<h2>Архив челленджа</h2>${days.map(d=>`<div class="history-item"><span>${d.date} · этап ${d.stage}<br>${esc(d.note)}</span><strong>${d.paused?'Пауза':evaluation(d).percent+'%'}</strong></div>`).join('')}<p class="hint">Полная история и действовавшие нормы доступны в JSON-экспорте.</p>`);});
}
async function enablePush(){if(!config.pushReady)return toast('Сначала настройте серверную отправку push');if(!('Notification'in window)||!('PushManager'in window))return toast('В этом браузере push недоступны');if(queue.length)return toast('Сначала синхронизируйте изменения');try{if(await Notification.requestPermission()!=='granted')return toast('Дневник доступен без уведомлений');const reg=await navigator.serviceWorker.ready,key=config.vapidPublicKey.replace(/-/g,'+').replace(/_/g,'/'),bytes=Uint8Array.from(atob(key.padEnd(Math.ceil(key.length/4)*4,'=')),c=>c.charCodeAt(0));const sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes});state=(await api('/api/push',{method:'POST',body:JSON.stringify(sub)})).state;await persist();toast('Уведомления включены');}catch(e){toast(e.message);}}
function openModal(html){closeModal();modalRestore=document.activeElement;const d=document.createElement('div');d.className='modal-backdrop';d.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="Диалог"><button class="close" aria-label="Закрыть">×</button>${html}</section>`;document.body.append(d);d.querySelector('.close').onclick=closeModal;d.onclick=e=>{if(e.target===d)closeModal();};d.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...d.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});d.querySelector('input,button')?.focus();}
function closeModal(){document.querySelector('.modal-backdrop')?.remove();modalRestore?.focus();}
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
async function load(){try{config=await api('/api/config');const data=await api('/api/me'),cached=await localGet('session');user={id:data.id,email:data.email};queue=cached?.user.id===user.id?cached.queue:[];state=data.state;for(const op of queue)try{apply(state,op.action);}catch{}saveStatus=queue.length?'pending':'saved';await persist();render();await sync();}catch(e){if(e.status===401){user=null;renderAuth();}else{const cache=await localGet('session');if(cache){({user,state,queue,config}=cache);saveStatus='pending';render();toast('Нет соединения. Дневник доступен из кеша.');}else{$('#app').innerHTML='<div class="loading">Нет соединения<span>Для первого входа нужен интернет.</span></div>';}}}}
window.addEventListener('online',()=>{if(user)sync();else load();});
setInterval(()=>{if(user&&queue.length&&!document.querySelector('.modal-backdrop'))sync();},30000);
window.addEventListener('focus',()=>{if(user&&queue.length)sync();});
window.addEventListener('pageshow',e=>{if(e.persisted)load();});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Автономный режим недоступен. Проверьте HTTPS.'));
await load();

document.addEventListener("click",async e=>{const link=e.target.closest("a[data-pages-export]");if(!link)return;e.preventDefault();try{await sync();await downloadBrowserExport(link.dataset.pagesExport);}catch(error){toast(error.message);}});
